/// Bite-sized daily lessons. One per subject per day, rotating; each has a 1-question quiz.
class Lesson {
  final String title, body, question, link;
  final List<String> options;
  final int answer;
  const Lesson(this.title, this.body, this.question, this.options, this.answer, this.link);
}

class Subject {
  final String id, name, emoji;
  final int color;
  final List<Lesson> lessons;
  const Subject(this.id, this.name, this.emoji, this.color, this.lessons);
}

