int dayOfYear([DateTime? d]) {
  final t = d ?? DateTime.now();
  return t.difference(DateTime(t.year)).inDays;
}

/// Today's lesson for a subject (rotates daily, each subject offset so they don't sync up).
int todaysIndex(Subject s, [int skip = 0]) => (dayOfYear() + subjects.indexOf(s) * 3 + skip) % s.lessons.length;
